// Generate signed re-verification link (HMAC of player_id + timestamp + secret)
const crypto = require('crypto');
const player = $json;
const SECRET = $env.KYC_LINK_HMAC_SECRET || 'replace-with-bao-vault-injected';
const exp = Math.floor(Date.now() / 1000) + 7 * 86400;
const payload = `${player.player_id}.${exp}`;
const sig = crypto.createHmac('sha256', SECRET).update(payload).digest('hex');
return [{ json: { ...player, link: `https://kyc.example.internal/reverify?p=${player.player_id}&exp=${exp}&sig=${sig}` } }];
